/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(ProdTable, StatusDecreaseButton), FormControlEventType::Clicked)]
public static void StatusDecreaseButton_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e;
    FormDataSource fdsProdTable = sender.formRun().dataSource(formDataSourceStr(ProdTable, ProdTable));

    if (!ProdTable::NDX_StatusDecreaseAllowed(fdsProdTable))
    {
        ce.CancelSuperCall();
    }
}
